import{_ as e,o,c as d,a6 as a}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"状态行","description":"HTTP-version、status-code 三位数字、reason-phrase——响应起始行逐字段解析。","frontmatter":{"title":"状态行","description":"HTTP-version、status-code 三位数字、reason-phrase——响应起始行逐字段解析。","source":"https://daiw.org/manual/http11/status-line"},"headers":[],"relativePath":"manual/computer-programming/http11/status-line.md","filePath":"manual/computer-programming/http11/status-line.md"}'),s={name:"manual/computer-programming/http11/status-line.md"};function r(n,t,c,i,l,p){return o(),d("div",null,[...t[0]||(t[0]=[a(`<h1 id="状态行" tabindex="-1">状态行 <a class="header-anchor" href="#状态行" aria-label="Permalink to &quot;状态行&quot;">​</a></h1><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>status-line   = HTTP-version SP status-code SP reason-phrase</span></span>
<span class="line"><span>status-code   = 3DIGIT</span></span>
<span class="line"><span>reason-phrase = 1*( HTAB / SP / VCHAR / obs-text )</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 404 Not Found</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>三段之间<strong>各恰好一个 SP</strong>。注意 <code>reason-phrase</code> 在 ABNF 里是 <code>1*</code>，但实践中允许为空——此时形如 <code>HTTP/1.1 200</code> （状态码后仍有一个 SP）。</p><h2 id="status-code" tabindex="-1">status-code <a class="header-anchor" href="#status-code" aria-label="Permalink to &quot;status-code&quot;">​</a></h2><p><strong>恰好三位数字</strong>，不多不少。首位决定类别：</p><table tabindex="0"><thead><tr><th>类别</th><th>含义</th><th>客户端对未知码的处理</th></tr></thead><tbody><tr><td><code>1xx</code></td><td>信息性，中间响应</td><td>忽略该中间响应，继续等最终响应</td></tr><tr><td><code>2xx</code></td><td>成功</td><td>当作 <code>200</code></td></tr><tr><td><code>3xx</code></td><td>重定向</td><td>当作 <code>300</code>（不自动跟随）</td></tr><tr><td><code>4xx</code></td><td>客户端错误</td><td>当作 <code>400</code></td></tr><tr><td><code>5xx</code></td><td>服务端错误</td><td>当作 <code>500</code></td></tr></tbody></table><p><strong>关键规则</strong>：客户端 <strong>MUST</strong> 理解类别，但<strong>不必</strong>理解每个具体码；遇到不认识的状态码时，按该类别的 <code>x00</code> 处理。这使得新增状态码无需改造客户端。首位为 <code>0</code> 或 <code>6</code>–<code>9</code> 的码非法。</p><p>具体每个码的触发条件见<a href="/Front2Full/manual/computer-programming/http11/status-codes">状态码</a>。</p><h2 id="reason-phrase" tabindex="-1">reason-phrase <a class="header-anchor" href="#reason-phrase" aria-label="Permalink to &quot;reason-phrase&quot;">​</a></h2><p>纯人类可读描述，<strong>无语义</strong>。要点：</p><ul><li>客户端 <strong>MUST NOT</strong> 依据它做任何逻辑判断——只看状态码。</li><li>服务端可自定义甚至置空；<code>HTTP/1.1 200 OK</code> 与 <code>HTTP/1.1 200 Yay</code> 完全等价。</li><li>允许 <code>obs-text</code>（0x80–0xFF），但编码未定义，不应使用非 ASCII。</li><li>HTTP/2 与 HTTP/3 中该字段<strong>已彻底移除</strong>——它不携带信息，是纯历史遗留。</li></ul><h2 id="_1xx-的特殊性" tabindex="-1">1xx 的特殊性 <a class="header-anchor" href="#_1xx-的特殊性" aria-label="Permalink to &quot;1xx 的特殊性&quot;">​</a></h2><p><code>1xx</code> 是<strong>中间响应</strong>：一次请求可先收到零或多个 <code>1xx</code>，最后才是唯一的最终响应（<code>2xx</code>–<code>5xx</code>）。</p><ul><li><code>1xx</code> 响应<strong>终止于其后的空行，且恒无消息体</strong>——不受 <code>Content-Length</code> 影响。</li><li>HTTP/1.0 客户端不认识 <code>1xx</code>，服务端 <strong>MUST NOT</strong> 向其发送。</li></ul><table tabindex="0"><thead><tr><th>码</th><th>语义</th></tr></thead><tbody><tr><td><code>100 Continue</code></td><td>已收到请求头，客户端可继续发送请求体。配合 <code>Expect: 100-continue</code> 使用</td></tr><tr><td><code>101 Switching Protocols</code></td><td>服务端同意按 <code>Upgrade</code> 切换协议（WebSocket 握手即用此码）</td></tr><tr><td><code>102 Processing</code></td><td>（WebDAV，RFC 2518）已废弃</td></tr><tr><td><code>103 Early Hints</code></td><td>先行给出 <code>Link</code> 等预加载提示，最终响应随后到达</td></tr></tbody></table><h2 id="与消息体的关系" tabindex="-1">与消息体的关系 <a class="header-anchor" href="#与消息体的关系" aria-label="Permalink to &quot;与消息体的关系&quot;">​</a></h2><p>状态码直接决定响应<strong>能否有体</strong>，且优先级高于 <code>Content-Length</code>：</p><table tabindex="0"><thead><tr><th>状态码</th><th>消息体</th></tr></thead><tbody><tr><td><code>1xx</code></td><td><strong>恒无</strong></td></tr><tr><td><code>204 No Content</code></td><td><strong>恒无</strong></td></tr><tr><td><code>304 Not Modified</code></td><td><strong>恒无</strong>（但可带 <code>Content-Length</code>，指代若返回 200 时的长度，接收方不得据此读体）</td></tr><tr><td><code>2xx</code> 对 CONNECT</td><td>无体；其后字节属于隧道</td></tr><tr><td>其余</td><td>由成帧规则决定</td></tr></tbody></table><p>对 <strong>HEAD</strong> 请求的响应恒无体，与状态码无关——但其头字段应与对应 GET 一致。详见<a href="/Front2Full/manual/computer-programming/http11/message-body-length">消息体长度</a>。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/field-syntax">字段行语法</a>——字段名、值、OWS 与重复字段的合并规则。</p>`,22)])])}const g=e(s,[["render",r]]);export{u as __pageData,g as default};
